static func getHardwareName(): String {
    try {
        let p = Runtime.getRuntime().exec("uname -m")
        p.waitFor()
        let in__ = p.getInputStream()
        try {
            return readFully(in__)
        } finally {
            in__.close()
        }
    } catch (e: Throwable) {
        System.err.println("Error while running uname -m: " + e.getMessage())
        return "unknown"
    }
}
